SELECT p.slug project,r.display_name repository,l.root_path,s.path,d.dependency_name,d.requirement,d.dependency_kind,d.target,d.optional FROM repository_dependencies d JOIN source_documents s ON s.id=d.source_document_id JOIN repository_locations l ON l.id=d.repository_location_id JOIN repositories r ON r.id=l.repository_id JOIN projects p ON p.id=r.project_id WHERE p.slug=$1 AND l.is_present AND d.dependency_name ILIKE ANY($2::text[]) AND ($3::text[] IS NULL OR EXISTS (SELECT 1 FROM unnest($3::text[]) AS allowed(root_path) WHERE l.root_path=allowed.root_path)) ORDER BY d.dependency_name,r.display_name,l.root_path LIMIT 40
